    public void createSafeElement_SourceElementHasNoAttribute_DestElementHasNoAttribute(){
        // Given
        Element sourceEl = new Element(Tag.valueOf("p"), "");

        // When
        ElementMeta elementMeta = cleaner.createSafeElement(sourceEl);

        // Then
        assertThat(elementMeta.getElement().attributes().size(), is(0));
    }

    @Test
    public void createSafeElement_SourceElementHasOneSafeAttribute_DestElementHasOneAttribute(){
        // Given
        Whitelist whitelist = Whitelist.none().addTags("p").addAttributes("p", "style");
        cleaner = new Cleaner(whitelist);
        Attributes sourceAttrs = new Attributes();
        sourceAttrs.put("style", "color: red;");
        Element sourceEl = new Element(Tag.valueOf("p"), "").attr("style", "color: red;");

        // When
        ElementMeta elementMeta = cleaner.createSafeElement(sourceEl);

        // Then
        assertThat(elementMeta.getElement().attributes().size(), is(1));
    }

    @Test
    public void createSafeElement_SourceElementHasOneUnsafeAttribute_DestElementHasNoAttribute(){
        // Given
        Whitelist whitelist = Whitelist.none().addTags("p");
        Element sourceEl = new Element(Tag.valueOf("p"), "").attr("onclick", "alert();");

        // When
        ElementMeta elementMeta = cleaner.createSafeElement(sourceEl);

        // Then
        assertThat(elementMeta.getElement().attributes().size(), is(0));
    }

    @Test
    public void createSafeElement_SourceElementHasEnforcedAttribute_DestElementHasEnforcedAttribute(){
        // Given
        Whitelist whitelist = Whitelist.none().addTags("p").addEnforcedAttribute("p", "class", "my-class");
        Element sourceEl = new Element(Tag.valueOf("p"), "");

        // When
        ElementMeta elementMeta = cleaner.createSafeElement(sourceEl);

        // Then
        assertThat(elementMeta.getElement().attributes().size(), is(1));
        assertThat(elementMeta.getElement().attr("class"), is("my-class"));
    }

    @Test
    public void createSafeElement_SourceElementHasMultipleAttributes_DestElementHasFilteredAttributes(){
        // Given
        Whitelist whitelist = Whitelist.none().addTags("p").addAttributes("p", "style").addEnforcedAttribute("p", "class", "my-class");
        Attributes sourceAttrs = new Attributes();
        sourceAttrs.put("style", "color: red;");
        sourceAttrs.put("onclick", "alert();");
        Element sourceEl = new Element(Tag.valueOf("p"), "").attr("style", "color: red;").attr("onclick", "alert();");

        // When
        ElementMeta elementMeta = cleaner.createSafeElement(sourceEl);

        // Then
        assertThat(elementMeta.getElement().attributes().size(), is(2));
        assertThat(elementMeta.getElement().attr("style"), is("color: red;"));
        assertThat(elementMeta.getElement().attr("class"), is("my-class"));
    }

    @Test
    public void createSafeElement_SourceElementIsNull_ThrowsException(){
        // Given
        Element sourceEl = null;

        // When and Then
        try {
            cleaner.createSafeElement(sourceEl);
            Assert.fail("Expected NullPointerException");
        } catch (NullPointerException e) {}
    }
