    public void testSolveRoots(){
        solver = new BaseSecantSolver(1e-6, BaseSecantSolver.Method.ILLINOIS);
        assertEquals(-2, solver.solve(Integer.MAX_VALUE, new UnivariateRealFunction() {
            @Override
            public double value(double x) {
                return x * x - 4;
            }
